@Service
public class AccountService {
    @Autowired private AccountRepository accountRepo;

    @Transactional  // Wraps method in ACID transaction
    public void transfer(Long fromId, Long toId, BigDecimal amount) {
        var fromAccount = accountRepo.findById(fromId)
            .orElseThrow(() -> new AccountNotFoundException(fromId));
        var toAccount = accountRepo.findById(toId)
            .orElseThrow(() -> new AccountNotFoundException(toId));

        if (fromAccount.balance().compareTo(amount) < 0) {
            throw new InsufficientFundsException();  // Atomicity: rolls back entire operation
        }

        fromAccount.withdraw(amount);  // Consistency: enforces balance >= 0 rule
        toAccount.deposit(amount);     // Isolation: other threads see old or new state, never half-done

        accountRepo.save(fromAccount);
        accountRepo.save(toAccount);   // Durability: committed changes survive server crash
    }
}

@Service
public class OrderService {
    @Autowired private OrderRepository orderRepo;
    @Autowired private InventoryService inventoryService;

    @Transactional  // ✓ Works: public method on Spring bean
    public void placeOrder(OrderRequest request) {
        var order = new Order(request.userId(), request.items());
        orderRepo.save(order);
        inventoryService.reserveStock(order);  // ✓ New transaction or joins existing
        sendConfirmationEmail(order);  // ✗ No transaction! Self-invocation bypasses proxy
    }

    @Transactional  // ✗ Never called through proxy
    private void sendConfirmationEmail(Order order) {
        // This transaction won't start because private methods aren't proxied
        // If this throws an exception, placeOrder's transaction won't roll back this part
    }

    // ✓ Fix: extract to separate bean or make public and call via self-reference
    @Transactional(propagation = Propagation.REQUIRES_NEW)  // Starts new transaction
    public void recordAuditLog(String action) {
        // Always commits separately, even if caller's transaction rolls back
    }
}
